#!/usr/bin/env node
/* Builds generated files:
 *   figma-plugin/code.js       = shared/geom.js + figma-plugin/src/serializer.js + figma-plugin/src/main.js
 *   ae-extension/host/geom.jsx = shared/geom.js (ExtendScript copy)
 *   figma-plugin/ui.html       = figma-plugin/src/ui.html with {{asset:file}} inlined as data URIs from
 *                                figma-plugin/assets/ and {{version}} from package.json (Figma plugin UIs are one file)
 */
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "..");
const read = (p) => fs.readFileSync(path.join(root, p), "utf8");
const banner = "/* GENERATED by scripts/build.js - edit sources in shared/ and figma-plugin/src/ */\n";
const strip = (s) => s.replace(/\nif \(typeof module !== "undefined" && module\.exports\) \{[^\n]*\}\s*$/, "\n");
const code = banner + strip(read("shared/geom.js")) + "\n" + strip(read("figma-plugin/src/serializer.js")) + "\n" + read("figma-plugin/src/main.js");
fs.writeFileSync(path.join(root, "figma-plugin/code.js"), code);
fs.writeFileSync(path.join(root, "ae-extension/host/geom.jsx"), banner + read("shared/geom.js"));
const pkg = JSON.parse(read("package.json"));
const MIME = { ".svg": "image/svg+xml", ".png": "image/png" };
let ui = read("figma-plugin/src/ui.html").replace(/\{\{asset:([\w.-]+)\}\}/g, (m, file) => {
  const p = path.join(root, "figma-plugin/assets", file);
  if (!fs.existsSync(p)) throw new Error("ui.html references a missing asset: " + file);
  return "data:" + MIME[path.extname(file)] + ";base64," + fs.readFileSync(p).toString("base64");
}).replace(/\{\{version\}\}/g, pkg.version);
// prefers-color-scheme fallback (outside Figma, or before Figma sets html.figma-dark / .figma-light):
// the html.figma-dark rules are repeated under the media query for html without either class.
{
  const start = ui.indexOf("  html.figma-dark {");
  const end = ui.indexOf("}", start) + 1;
  if (start < 0) throw new Error("ui.html: html.figma-dark block not found");
  const auto = "html:not(.figma-light):not(.figma-dark)";
  const tokens = ui.slice(start, end).replace("html.figma-dark", auto);
  ui = ui.replace("/*@@DARK_MEDIA@@*/", "@media (prefers-color-scheme: dark) {\n  " + tokens.trim() + "\n  }")
    .replace("/*@@DARK_MEDIA_ASSETS@@*/", "@media (prefers-color-scheme: dark) { " + auto + " .dark-only { display: block !important; } " + auto + " .light-only { display: none !important; } }");
}
ui = ui.replace("<!-- SOURCE of figma-plugin/ui.html. scripts/build.js inlines the asset placeholders from figma-plugin/assets/ as data URIs. -->",
  "<!-- GENERATED by scripts/build.js from figma-plugin/src/ui.html - edit that file -->");
if (/\{\{[a-z]+(:[^}]*)?\}\}/.test(ui)) throw new Error("unresolved placeholder in ui.html");
fs.writeFileSync(path.join(root, "figma-plugin/ui.html"), ui);
console.log("built figma-plugin/ui.html (" + ui.length + " bytes)");
console.log("built figma-plugin/code.js (" + code.length + " bytes), ae-extension/host/geom.jsx");
